use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        res.len() == (if numbers.len() == 0 {0} else { 2 * numbers.len() - 1 }) &&
        // for all i < numbers.len(), res[2*i] == numbers[i]
        (forall|i: usize| (i < numbers.len()) ==> res[2*i] == numbers[i]) &&
        // for all j < res.len(), if j odd then res[j] == delim
        (forall|j: usize| (j < res.len() && j % 2 == 1) ==> res[j] == delim) &&
        // if numbers empty then res empty (already ensured by length)
        (numbers.len() == 0 ==> res.len() == 0)
{
    if numbers.len() == 0 {
        return vec![];
    }

    let n = numbers.len();
    let mut res = Vec::with_capacity(2 * n - 1);

    let mut i = 0usize;
    while i < n
        invariant
            i <= n,
            res.len() == 2*i.saturating_sub(1).max(0),
            // For filled entries at even indices
            (forall|k: usize| (k < i) ==> res[2*k] == numbers[k]),
            // For filled delimiter entries at odd indices
            (forall|k: usize| (k + 1 < res.len() && (k*2+1) < res.len()) ==> res[k*2+1] == delim),
        decreases n - i,
    {
        // Push number at even index (2*i)
        res.push(numbers[i]);

        // After pushing number, if not at last element, push delimiter
        if i < n - 1 {
            res.push(delim);
        }

        i = i + 1;
    }

    res
}

}
